await build({ entryPoints: [root + '/src/module.ts'], bundle: true, format: 'esm', platform: 'node', outfile: outdir + '/orig.mjs', absWorkingDir: root, logLevel: 'error' });
await build({ entryPoints: [root + '/out/module.ts'], bundle: true, format: 'esm', platform: 'node', outfile: outdir + '/new.mjs', absWorkingDir: root, logLevel: 'error' });
const A = await import(outdir + '/orig.mjs');
const B = await import(outdir + '/new.mjs');
const names = ['kim','park','lee','choi','jung'];
const rnd = n => Math.floor(Math.random() * n);
const rowOf = () => ({ id: rnd(10), name: names[rnd(5)], age: 18 + rnd(43) });
let fails = 0, n = 0;
const same = (x, y) => Object.is(x, y) || JSON.stringify(x) === JSON.stringify(y);
const check = (label, a, b) => { n++; if (!same(a, b)) { fails++; if (fails < 10) console.log('DIFF', label, a, b); } };
// publicFields
for (let i = 0; i < 2000; i++) { const r = rowOf(); check('pf ' + JSON.stringify(r), A.publicFields(r), B.publicFields(r)); }
// totalAge
for (let i = 0; i < 2000; i++) { const len = rnd(13); const rows = Array.from({ length: len }, rowOf); check('ta', A.totalAge(rows), B.totalAge(rows)); }
check('ta empty', A.totalAge([]), B.totalAge([]));
// parseAmount: alphabet digits . + - space e x, length 0..8
const alpha = '0123456789.+- ex';
const pa = s => [A.parseAmount(s), B.parseAmount(s)];
for (let i = 0; i < 50000; i++) { const len = rnd(9); let s = ''; for (let j = 0; j < len; j++) s += alpha[rnd(alpha.length)]; const [a, b] = pa(s); check('pa ' + JSON.stringify(s), a, b); }
for (const s of ['', ' ', '92858+99', '.72e', '0x1F', '-0x1f', '0b11', '0o7', ' 12 ', '1e3', '-.5', '+.5e-1', 'e', 'x', '1 2', '00012', '1e', '1.', '.']) { const [a, b] = pa(s); check('pa ' + JSON.stringify(s), a, b); }
console.log(`checked ${n}, mismatches ${fails}`);
console.log('examples', A.publicFields({id:1,name:'jung',age:24}), B.publicFields({id:1,name:'jung',age:24}), A.totalAge([{id:9,name:'kim',age:45},{id:6,name:'park',age:30},{id:9,name:'lee',age:49}]), B.totalAge([{id:9,name:'kim',age:45},{id:6,name:'park',age:30},{id:9,name:'lee',age:49}]), A.parseAmount('92858+99'), B.parseAmount('92858+99'), A.parseAmount('.72e'), B.parseAmount('.72e'));
EOF
S="$S" node "$S/compare.mjs" 2>&1 | tail -20; echo; echo "scratch: $S"

